+        <div class="col"><div class="stat-card p-2 text-center rounded">Done: <strong>@GetColumnTasks("Done").Count</strong></div></div>
+        <div class="col"><div class="stat-card stat-overdue p-2 text-center rounded">Overdue: <strong>@FilteredTasks.Count(t => t.DueDate.Date < DateTime.Today)</strong></div></div>
+    </div>
+
+    <!-- Search Bar -->
+    <div class="mb-3">
+        <input type="text" class="form-control" placeholder="Search tasks by title..."
+               @bind="_searchText" @bind:event="oninput" />
+    </div>
+
+    <!-- Kanban Columns -->
+    <div class="row g-3">
+        @foreach (var column in Columns)
+        {
+            var tasks = GetColumnTasks(column);
+            var colIndex = Array.IndexOf(Columns, column);
+
+            <div class="col-md-4">
+                <div class="kanban-column rounded p-3">
+                    <h5 class="kanban-header mb-3">@column <span class="badge bg-secondary ms-1">@tasks.Count</span></h5>
+
+                    @foreach (var task in tasks)
+                    {
+                        <div class="card task-card mb-2">
+                            <div class="card-body p-2">
+                                <h6 class="card-title mb-1">@task.Title</h6>
+                                <p class="card-text mb-1 text-muted small">@task.Assignee</p>
+                                <div class="d-flex justify-content-between align-items-center mb-1">
+                                    <span class="badge priority-@task.Priority.ToLowerInvariant()">@task.Priority</span>
+                                    <small class="text-muted">@task.DueDate.ToString("MMM dd")</small>
+                                </div>
+                                <div class="d-flex gap-1 mt-1">
+                                    @if (colIndex > 0)
+                                    {
+                                        <button class="btn btn-sm btn-outline-secondary flex-fill"
+                                                disabled="@_moving"
+                                                @onclick="() => MoveTaskAsync(task.Id, Columns[colIndex - 1])">
+                                            &larr; Move Left
+                                        </button>
+                                    }
+                                    @if (colIndex < Columns.Length - 1)
+                                    {
+                                        <button class="btn btn-sm btn-outline-secondary flex-fill"
+                                                disabled="@_moving"
+                                                @onclick="() => MoveTaskAsync(task.Id, Columns[colIndex + 1])">
+                                            Move Right &rarr;
+                                        </button>
+                                    }
+                                </div>
+                            </div>
+                        </div>
+                    }
+
+                    @if (_addingColumn == column)
+                    {
+                        <div class="card mt-2">
+                            <div class="card-body p-2">
+                                <input type="text" class="form-control form-control-sm mb-1"
+                                       placeholder="Title" @bind="_newTitle" />
+                                <input type="text" class="form-control form-control-sm mb-1"
+                                       placeholder="Assignee" @bind="_newAssignee" />
+                                <select class="form-select form-select-sm mb-1" @bind="_newPriority">
+                                    <option value="High">High</option>
+                                    <option value="Medium">Medium</option>
+                                    <option value="Low">Low</option>
+                                </select>
+                                <input type="date" class="form-control form-control-sm mb-2"
+                                       @bind="_newDueDate" />
+                                <div class="d-flex gap-1">
+                                    <button class="btn btn-sm btn-primary flex-fill"
+                                            disabled="@_saving"
+                                            @onclick="() => SaveTaskAsync(column)">
+                                        @(_saving ? "Saving..." : "Save")
+                                    </button>
+                                    <button class="btn btn-sm btn-outline-secondary flex-fill"
+                                            @onclick="CancelAdd">Cancel</button>
+                                </div>
+                            </div>
+                        </div>
+                    }
+                    else
+                    {
+                        <button class="btn btn-sm btn-outline-primary w-100 mt-2"
+                                @onclick="() => ShowAddForm(column)">
+                            + Add Task
+                        </button>
+                    }
+                </div>
+            </div>
+        }
+    </div>
+}
+
+@code {
+    private static readonly string[] Columns = ["To Do", "In Progress", "Done"];
+
+    private List<TaskItem> _tasks = [];
+    private bool _loading = true;
+    private string? _error;
+    private string _searchText = string.Empty;
+    private bool _moving;
+
+    // Add-task form state
+    private string? _addingColumn;
+    private string _newTitle = string.Empty;
+    private string _newAssignee = string.Empty;
+    private string _newPriority = "Medium";
+    private DateTime _newDueDate = DateTime.Today.AddDays(7);
+    private bool _saving;
+
+    private List<TaskItem> FilteredTasks =>
+        string.IsNullOrWhiteSpace(_searchText)
+            ? _tasks
+            : _tasks.Where(t => t.Title.Contains(_searchText, StringComparison.OrdinalIgnoreCase)).ToList();
+
+    private List<TaskItem> GetColumnTasks(string status) =>
+        FilteredTasks.Where(t => t.Status == status).ToList();
+
+    protected override async Task OnInitializedAsync()
+    {
+        await LoadTasksAsync();
+    }
+
+    private async Task LoadTasksAsync()
+    {
+        try
+        {
+            _loading = true;
+            _error = null;
+            _tasks = await TaskService.GetAllTasksAsync();
+        }
+        catch (Exception ex)
+        {
+            _error = ex.Message;
+        }
+        finally
+        {
+            _loading = false;
+        }
+    }
+
+    private async Task MoveTaskAsync(int taskId, string newStatus)
+    {
+        try
+        {
+            _moving = true;
+            await TaskService.UpdateTaskStatusAsync(taskId, newStatus);
+            var task = _tasks.First(t => t.Id == taskId);
+            _tasks[_tasks.IndexOf(task)] = task with { Status = newStatus };
+        }
+        catch (Exception ex)
+        {
+            _error = ex.Message;
+        }
+        finally
+        {
+            _moving = false;
+        }
+    }
+
+    private void ShowAddForm(string column)
+    {
+        _addingColumn = column;
+        _newTitle = string.Empty;
+        _newAssignee = string.Empty;
+        _newPriority = "Medium";
+        _newDueDate = DateTime.Today.AddDays(7);
+    }
+
+    private void CancelAdd() => _addingColumn = null;
+
+    private async Task SaveTaskAsync(string column)
+    {
+        if (string.IsNullOrWhiteSpace(_newTitle))
+            return;
+
+        try
+        {
+            _saving = true;
+            var created = await TaskService.CreateTaskAsync(_newTitle.Trim(), _newAssignee.Trim(), _newPriority, _newDueDate);
+            // If the service doesn't set the status to the target column, update it
+            if (created.Status != column)
+            {
+                await TaskService.UpdateTaskStatusAsync(created.Id, column);
+                created = created with { Status = column };
+            }
+            _tasks.Add(created);
+            _addingColumn = null;
+        }
+        catch (Exception ex)
+        {
+            _error = ex.Message;
+        }
+        finally
+        {
+            _saving = false;
+        }
+    }
+}
+

